const body = $input.first().json.body || $input.first().json;

const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = n => new Intl.NumberFormat('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n) || 0);

const idioma = (body.idioma === 'en') ? 'en' : 'es';

const T = {
  es: {
    titulo: 'COTIZACIÓN', folio: 'Folio', fecha: 'Fecha', cliente: 'Cliente',
    atencion: 'Atención', vigencia: 'Vigencia', ruta: 'Ruta', modalidad: 'Modalidad',
    incoterm: 'Incoterm', mercancia: 'Mercancía', carga: 'Detalle de la carga',
    concepto: 'Concepto', importe: 'Importe', subtotal: 'Subtotal', total: 'Total',
    notas: 'Notas y condiciones', sinVigencia: 'Sujeta a confirmación',
    piePagina: 'Esta cotización no incluye cargos que surjan por causas ajenas a lo aquí descrito.',
    contacto: 'Contacto'
  },
  en: {
    titulo: 'QUOTATION', folio: 'Reference', fecha: 'Date', cliente: 'Client',
    atencion: 'Attention', vigencia: 'Validity', ruta: 'Route', modalidad: 'Mode',
    incoterm: 'Incoterm', mercancia: 'Commodity', carga: 'Cargo details',
    concepto: 'Description', importe: 'Amount', subtotal: 'Subtotal', total: 'Total',
    notas: 'Notes and conditions', sinVigencia: 'Subject to confirmation',
    piePagina: 'This quotation does not include charges arising from causes other than those described herein.',
    contacto: 'Contact'
  }
}[idioma];

const lineas = Array.isArray(body.lineas) ? body.lineas : [];
const porMoneda = {};
for (const l of lineas) {
  const m = l.moneda || 'USD';
  if (!porMoneda[m]) porMoneda[m] = { lineas: [], total: 0 };
  porMoneda[m].lineas.push(l);
  porMoneda[m].total += Number(l.venta) || 0;
}
const monedas = Object.keys(porMoneda);
const filas = monedas.map(m => {
  const g = porMoneda[m];
  const renglones = g.lineas.map(l => `
    <tr>
      <td class="concepto">${esc(l.concepto)}${l.detalle ? `<span class="detalle">${esc(l.detalle)}</span>` : ''}</td>
      <td class="importe">${num(l.venta)}</td>
    </tr>`).join('');
  return `
    <table class="conceptos">
      <thead>
        <tr>
          <th>${T.concepto}</th>
          <th class="importe">${T.importe} ${esc(m)}</th>
        </tr>
      </thead>
      <tbody>${renglones}</tbody>
      <tfoot>
        <tr>
          <td class="total-label">${T.total} ${esc(m)}</td>
          <td class="total-monto">${num(g.total)}</td>
        </tr>
      </tfoot>
    </table>`;
}).join('');

const carga = body.carga || {};
const detallesCarga = [];
if (carga.tipo) detallesCarga.push(['Tipo', carga.tipo.toUpperCase()]);
if (carga.contenedores) detallesCarga.push(['Contenedores', carga.contenedores]);
if (carga.piezas) detallesCarga.push([idioma==='es'?'Piezas':'Pieces', carga.piezas]);
if (carga.peso) detallesCarga.push([idioma==='es'?'Peso':'Weight', carga.peso + ' kg']);
if (carga.volumen) detallesCarga.push([idioma==='es'?'Volumen':'Volume', carga.volumen + ' m³']);
const filasCarga = detallesCarga.map(([k,v]) => `<div class="dato"><span class="k">${esc(k)}</span><span class="v">${esc(v)}</span></div>`).join('');

const html = `<!DOCTYPE html>
<html lang="${idioma}">
<head>
<meta charset="utf-8">
<style>
  @page { size: letter; margin: 18mm 16mm; }
  * { box-sizing: border-box; }
  body { font-family: Helvetica, Arial, sans-serif; color: #1F2937; font-size: 10pt; margin: 0; }
  .encabezado { display: flex; justify-content: space-between; align-items: flex-start;
                border-bottom: 2px solid #E11D48; padding-bottom: 14px; margin-bottom: 20px; }
  .marca { font-size: 24pt; font-weight: bold; letter-spacing: -0.5px; }
  .marca .v { color: #E11D48; }
  .marca .resto { color: #1F2937; }
  .marca-sub { font-size: 8pt; color: #6B7280; margin-top: 2px; }
  .doc { text-align: right; }
  .doc-titulo { font-size: 15pt; font-weight: bold; color: #E11D48; letter-spacing: 1px; }
  .doc-folio { font-family: 'Courier New', monospace; font-size: 11pt; margin-top: 4px; }
  .doc-fecha { font-size: 9pt; color: #6B7280; margin-top: 2px; }
  .vigencia { background: #FEF3C7; border-left: 3px solid #D97706; padding: 9px 13px;
              margin-bottom: 18px; font-size: 10pt; }
  .vigencia strong { color: #92400E; }
  .bloques { display: flex; gap: 22px; margin-bottom: 20px; }
  .bloque { flex: 1; }
  .bloque h3 { font-size: 8pt; text-transform: uppercase; letter-spacing: 0.6px;
               color: #6B7280; margin: 0 0 7px 0; font-weight: bold; }
  .dato { display: flex; gap: 8px; font-size: 9.5pt; margin-bottom: 3px; }
  .dato .k { color: #6B7280; min-width: 78px; }
  .dato .v { color: #1F2937; font-weight: 500; }
  .cliente-nombre { font-size: 12pt; font-weight: bold; margin-bottom: 5px; }
  table.conceptos { width: 100%; border-collapse: collapse; margin-bottom: 16px; }
  table.conceptos th { background: #1F2937; color: #fff; padding: 8px 11px;
                       font-size: 8.5pt; text-transform: uppercase; letter-spacing: 0.4px;
                       text-align: left; }
  table.conceptos th.importe, table.conceptos td.importe { text-align: right; }
  table.conceptos td { padding: 8px 11px; border-bottom: 1px solid #E5E7EB; font-size: 10pt; }
  table.conceptos td.concepto { color: #1F2937; }
  table.conceptos .detalle { display: block; font-size: 8.5pt; color: #6B7280; margin-top: 2px; }
  table.conceptos td.importe { font-variant-numeric: tabular-nums; }
  table.conceptos tfoot td { border-top: 2px solid #1F2937; border-bottom: none;
                             padding-top: 10px; font-weight: bold; font-size: 11pt; }
  table.conceptos tfoot .total-monto { text-align: right; color: #E11D48;
                                       font-variant-numeric: tabular-nums; }
  .notas { margin-top: 22px; padding-top: 14px; border-top: 1px solid #E5E7EB; }
  .notas h3 { font-size: 8pt; text-transform: uppercase; letter-spacing: 0.6px;
              color: #6B7280; margin: 0 0 6px 0; }
  .notas p { font-size: 9pt; line-height: 1.5; color: #374151; margin: 0 0 5px 0;
             white-space: pre-line; }
  .pie { margin-top: 26px; padding-top: 11px; border-top: 1px solid #E5E7EB;
         font-size: 8pt; color: #9CA3AF; line-height: 1.5; }
  .pie .contacto { color: #6B7280; margin-bottom: 4px; }
</style>
</head>
<body>
  <div class="encabezado">
    <div>
      <div class="marca"><span class="v">Vermur</span><span class="resto">Ops</span></div>
      <div class="marca-sub">Importaciones y Logística Vermur, S. de R.L. de C.V.</div>
    </div>
    <div class="doc">
      <div class="doc-titulo">${T.titulo}</div>
      <div class="doc-folio">${esc(body.folio || '')}</div>
      <div class="doc-fecha">${esc(body.fecha || new Date().toLocaleDateString(idioma === 'es' ? 'es-MX' : 'en-US'))}</div>
    </div>
  </div>
  <div class="vigencia">
    <strong>${T.vigencia}:</strong> ${esc(body.vigencia || T.sinVigencia)}
  </div>
  <div class="bloques">
    <div class="bloque">
      <h3>${T.cliente}</h3>
      <div class="cliente-nombre">${esc(body.cliente?.nombre || '')}</div>
      ${body.cliente?.contacto ? `<div class="dato"><span class="k">${T.atencion}</span><span class="v">${esc(body.cliente.contacto)}</span></div>` : ''}
      ${body.cliente?.correo ? `<div class="dato"><span class="k">Email</span><span class="v">${esc(body.cliente.correo)}</span></div>` : ''}
    </div>
    <div class="bloque">
      <h3>${T.carga}</h3>
      ${body.modalidad ? `<div class="dato"><span class="k">${T.modalidad}</span><span class="v">${esc(body.modalidad)}</span></div>` : ''}
      ${body.ruta ? `<div class="dato"><span class="k">${T.ruta}</span><span class="v">${esc(body.ruta)}</span></div>` : ''}
      ${body.incoterm ? `<div class="dato"><span class="k">${T.incoterm}</span><span class="v">${esc(body.incoterm)}</span></div>` : ''}
      ${body.mercancia ? `<div class="dato"><span class="k">${T.mercancia}</span><span class="v">${esc(body.mercancia)}</span></div>` : ''}
      ${filasCarga}
    </div>
  </div>
  ${filas}
  ${body.notas ? `<div class="notas"><h3>${T.notas}</h3><p>${esc(body.notas)}</p></div>` : ''}
  <div class="pie">
    ${body.contacto ? `<div class="contacto">${T.contacto}: ${esc(body.contacto)}</div>` : ''}
    ${T.piePagina}
  </div>
</body>
</html>`;

// ── El archivo se arma AQUÍ, en binario, con el HTML en UTF-8 (24-sep-2026) ──
// Antes lo hacía «HTML a archivo» (Convert to File · Move Base64 String to
// File), que espera BASE64 en la propiedad y recibía HTML en texto plano:
// decodificaba 14 bytes de basura y Gotenberg pintaba eso. El PDF salía
// siempre de 7,883 bytes con una sola línea ilegible.
// Gotenberg exige que el archivo se llame index.html; la propiedad binaria
// se llama «archivo» (sin punto: n8n lee «a.b» como ruta anidada).
const archivo = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{
  json: { nombreArchivo: `${body.folio || 'cotizacion'}.pdf`, folio: body.folio || '', bytesHtml: Buffer.byteLength(html, 'utf8') },
  binary: { archivo },
}];

const item = $input.first();
const nombre = $('Arma el HTML').first().json.nombreArchivo;
const bin = item.binary && item.binary.pdf;
if (!bin) {
  throw new Error('Gotenberg no devolvió el archivo PDF.');
}
// Un PDF válido empieza con «%PDF-». Si Gotenberg devolvió otra cosa, es
// error, no archivo: que lo diga el flujo y no el navegador.
const buffer = await this.helpers.getBinaryDataBuffer(0, 'pdf');
if (buffer.subarray(0, 5).toString('latin1') !== '%PDF-') {
  throw new Error('Gotenberg devolvió algo que no es un PDF: ' + buffer.subarray(0, 40).toString('latin1'));
}
bin.fileName = nombre;
bin.mimeType = 'application/pdf';
return [{ json: { ok: true, nombreArchivo: nombre, folio: $('Arma el HTML').first().json.folio, bytes: buffer.length }, binary: { pdf: bin } }];

// Rama de error: Gotenberg falló o devolvió algo que no es PDF. Antes el
// webhook no respondía y la Function esperaba hasta el timeout. Se contesta
// un JSON que el modal puede mostrar; el detalle técnico queda en el log
// de la ejecución de n8n.
const item = $input.first();
const detalle = (item.json && (item.json.error && (item.json.error.message || item.json.error))) || item.json?.message || 'sin detalle';
return [{ json: {
  ok: false,
  error: 'El generador de PDF falló al armar el documento. Vuelve a intentarlo; si se repite, avisa a sistemas.',
  detalle: String(detalle).slice(0, 500),
} }];
